// Small native regression probe: boundary topology, color ownership and preallocation guards.
using System;using System.IO;using System.Linq;using System.Reflection;using System.Runtime.CompilerServices;using System.Collections.Generic;using System.Drawing;
using Rhino.Geometry;using TopoptLab.GH;
class VoxelSurfaceProbe {
 [STAThread]static int Main(string[] args){string[] paths={args[0],args[1],args[2]};AppDomain.CurrentDomain.AssemblyResolve+=delegate(object sender,ResolveEventArgs e){foreach(string p in paths)foreach(string ext in new[]{".dll",".gha"}){string f=Path.Combine(p,new AssemblyName(e.Name).Name+ext);if(File.Exists(f))return Assembly.LoadFrom(f);}return null;};try{Test();return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static readonly int[][] Sides={new[]{0,3,2,1},new[]{4,5,6,7},new[]{0,1,5,4},new[]{1,2,6,5},new[]{2,3,7,6},new[]{3,0,4,7}};
 static string Point(Point3f p){return p.X.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+","+p.Y.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+","+p.Z.ToString("R",System.Globalization.CultureInfo.InvariantCulture);}
 static string[] Faces(Mesh m,bool colored){return Enumerable.Range(0,m.Faces.Count).Select(i=>{var f=m.Faces[i];var ids=new[]{f.A,f.B,f.C,f.D};var ordered=ids.Select(n=>Point(m.Vertices[n])).ToArray();string key=Enumerable.Range(0,4).Select(start=>string.Join("|",Enumerable.Range(0,4).Select(k=>ordered[(start+k)%4]))).OrderBy(x=>x).First();if(colored){Check(ids.All(n=>m.VertexColors[n].ToArgb()==m.VertexColors[f.A].ToArgb()),"Face color varies");key+="="+m.VertexColors[f.A].ToArgb();}return key;}).OrderBy(x=>x).ToArray();}
 static Mesh Old(Point3d[] nodes,int[][] hexes,bool[] include,Color[] colors){var faces=new Dictionary<string,Tuple<int[],int>>();for(int e=0;e<hexes.Length;e++)if(include==null||include[e])foreach(var side in Sides){int[] face=side.Select(k=>hexes[e][k]).ToArray();string key=string.Join(",",face.OrderBy(n=>n));if(faces.ContainsKey(key))faces.Remove(key);else faces.Add(key,Tuple.Create(face,e));}var mesh=new Mesh();foreach(var item in faces.Values){int k=mesh.Vertices.Count;foreach(int n in item.Item1){mesh.Vertices.Add(nodes[n]);if(colors!=null)mesh.VertexColors.Add(colors[item.Item2]);}mesh.Faces.AddFace(k,k+1,k+2,k+3);}if(colors==null){mesh.Vertices.CombineIdentical(true,true);mesh.Weld(Math.PI);}mesh.Normals.ComputeNormals();mesh.Compact();return mesh;}
 static double Volume(Mesh m){using(var props=VolumeMassProperties.Compute(m)){Check(props!=null,"Volume unavailable");return props.Volume;}}
 static void Compare(Mesh expected,Mesh actual,bool colored,string tag){Check(actual.IsValid,tag+" mesh invalid");Check(Faces(expected,colored).SequenceEqual(Faces(actual,colored)),tag+" face or owner mismatch");Check(Math.Abs(Volume(expected)-Volume(actual))<1e-8,tag+" orientation or volume differs");Check(actual.Normals.Count==actual.Vertices.Count,tag+" normals missing");if(!colored)Check(actual.IsClosed,tag+" boundary not closed");}
 static void BudgetTests(){var type=typeof(Domain3Data).Assembly.GetType("TopoptLab.GH.VoxelGeometryBudget");Check(type!=null,"Missing preallocation resource guard");Check((ulong)type.GetMethod("AvailableMemory").Invoke(null,null)>0,"Windows available memory unavailable");var method=type.GetMethod("Plan",new[]{typeof(double[]),typeof(double),typeof(int),typeof(ulong)});Check(method!=null,"Missing deterministic resource plan");Action<double[],double,int,ulong,bool> plan=(sizes,h,limit,ram,valid)=>{try{method.Invoke(null,new object[]{sizes,h,limit,ram});Check(valid,"Unsafe resource plan accepted");}catch(TargetInvocationException e){if(valid)throw;Check(e.InnerException is ArgumentException,"Unexpected guard failure");}};plan(new[]{250d,150d,25d},2.5,60000,4UL*1024*1024*1024,true);plan(new[]{250d,150d,25d},2,121875,4UL*1024*1024*1024,true);plan(new[]{250d,150d,25d},2.5,8000,4UL*1024*1024*1024,false);plan(new[]{250d,150d,25d},2,121875,1024UL*1024*1024,false);plan(new[]{2049d,1d,1d},1,2000000,64UL*1024*1024*1024,false);plan(new[]{2000d,2000d,2d},1,2000000,64UL*1024*1024*1024,false);plan(new[]{double.MaxValue,1d,1d},double.Epsilon,2000000,64UL*1024*1024*1024,false);plan(new[]{double.NaN,1d,1d},1,2000000,64UL*1024*1024*1024,false);Console.WriteLine("PASS resource guard: 60k/122k allowed; selected limit, memory, axis, overflow and nonfinite rejected");}
 [MethodImpl(MethodImplOptions.NoInlining)]static void Test(){using(var core=new Rhino.Runtime.InProcess.RhinoCore(new[]{"/nosplash","/notemplate"},Rhino.Runtime.InProcess.WindowStyle.NoWindow)){for(int variant=0;variant<4;variant++){int nx=variant==0?1:3,ny=variant==0?1:3,nz=variant==0?1:3;var active=Enumerable.Range(0,nx*ny*nz).Where(e=>variant!=2||e!=13).Where(e=>variant!=3||e%3<2).ToArray();var d=new Domain3Data{nx=nx,ny=ny,nz=nz,cell=2,origin=new[]{11d,-7d,4d},active=active,solid=new int[0]};var ids=active.SelectMany(d.Hex).Distinct().OrderBy(n=>n).ToArray();var map=ids.Select((n,i)=>new{n,i}).ToDictionary(v=>v.n,v=>v.i);var nodes=ids.Select(d.Node).ToArray();var hexes=active.Select(e=>d.Hex(e).Select(n=>map[n]).ToArray()).ToArray();var reference=Old(nodes,hexes,null,null);Compare(reference,d.Surface(),false,"Domain "+variant);Check(d.Surface().Faces.Count==new[]{6,54,60,42}[variant],"Unexpected exposed face count");Check(Math.Abs(Volume(d.Surface())-active.Length*8)<1e-8,"Physical volume differs");foreach(bool selected in new[]{false,true}){var include=selected?active.Select(e=>e%2==0).ToArray():null;var colors=active.Select(e=>Color.FromArgb(255,(e*37)%256,(e*79)%256,(e*113)%256)).ToArray();Compare(Old(nodes,hexes,include,colors),VoxelMesh.Build(nodes,hexes,include,colors,0),true,"Color "+variant+" "+selected);Compare(Old(nodes,hexes,include,null),VoxelMesh.Build(nodes,hexes,include,null,0),false,"Threshold "+variant+" "+selected);}}Console.WriteLine("PASS boundary topology: single cell, solid block, cavity, truncated block; colors, thresholds, orientation and volume");BudgetTests();}}
}
